    @Test
    fun `QA golden weapi matches the Swift algorithm byte for byte`() {
        for (case in cases) {
            val form = NeteaseCrypto.weapi(case.payload)
            assertEquals(
                "weapi params mismatch for ${case.name}",
                case.weapiParams,
                form["params"],
            )
            assertEquals(
                "weapi encSecKey mismatch for ${case.name}",
                case.weapiEncSecKey,
                form["encSecKey"],
            )
        }
    }

    @Test
    fun `QA golden eapi matches the Swift algorithm byte for byte`() {
        for (case in cases) {
            val form = NeteaseCrypto.eapi(case.apiPath, case.payload)
            assertEquals(
                "eapi params mismatch for ${case.name}",
                case.eapiParams,
                form["params"],
            )
        }
    }

    @Test
    fun `payload bytes are fed unmodified`() {
        // Guards the vector table itself: if hex decoding were wrong the other
        // two tests could pass or fail for the wrong reason.
        for (case in cases) {
            assertEquals("payload length for ${case.name}", case.payloadLength, case.payload.size)
        }
    }

    @Test
    fun `eapi output is uppercase hex and block aligned`() {
        for (case in cases) {
            val params = NeteaseCrypto.eapi(case.apiPath, case.payload).getValue("params")
            assertTrue(
                "eapi params must be uppercase hex for ${case.name}",
                params.all { it in "0123456789ABCDEF" },
            )
            assertEquals("hex length multiple of 32 for ${case.name}", 0, params.length % 32)
        }
    }

    @Test
    fun `weapi is stable across runs and sensitive to payload`() {
        val first = cases.first()
        val a = NeteaseCrypto.weapi(first.payload)
        val b = NeteaseCrypto.weapi(first.payload)
        assertEquals(a, b)
        val mutated = first.payload.copyOf().also { it[it.size - 1] = 'X'.code.toByte() }
        assertTrue(
            "a one-byte payload change must change weapi params",
            NeteaseCrypto.weapi(mutated)["params"] != a["params"],
        )
    }
